func ProxyFetch(w http.ResponseWriter, r *http.Request) {
    targetURL := r.URL.Query().Get("url")
    resp, err := http.Get(targetURL)
    if err != nil {
        http.Error(w, "Failed to fetch", 502)
        return
    }
    defer resp.Body.Close()
    body, _ := io.ReadAll(resp.Body)
    w.Write(body)
}
